TLM.f("Tempora/Quad3-3",{"officium":"Feria Quarta infra Hebdomadam III in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad3-0","sections":{"Introitus":[{"k":"ref","la":"Ps 30:7-8"},{"k":"text","la":"Ego autem in Dómino sperábo: exsultábo et lætábor in tua misericórdia: quia respexísti humilitátem meam."},{"k":"ref","la":"Ps 39:2"},{"k":"text","la":"In te, Dómine, sperávi, non confúndar in ætérnum: in justítia tua líbera me et éripe me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ego autem in Dómino sperábo: exsultábo et lætábor in tua misericórdia: quia respexísti humilitátem meam."}],"Oratio":[{"k":"text","la":"Præsta nobis, quǽsumus, Dómine: ut salutáribus jejúniis erudíti, a nóxiis quoque vítiis abstinéntes, propitiatiónem tuam facílius impetrémus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Exodi"},{"k":"ref","la":"Exod 20:12-24"},{"k":"text","la":"Hæc dicit Dóminus Deus: Honóra patrem tuum et matrem tuam, ut sis longǽvus super terram, quam Dóminus, Deus tuus, dabit tibi. Non occídes. Non mœcháberis. Non furtum fácies. Non loquéris contra próximum tuum falsum testimónium. Non concupísces domum próximi tui: nec desiderábis uxórem ejus, non servum, non ancíllam, non bovem, non ásinum nec ómnia, quæ illíus sunt. Cunctus autem pópulus vidébat voces, et lámpades, et sónitum búccinæ, montémque fumántem: et, pertérriti ac pavóre concússi, stetérunt procul, dicéntes Móysi: Lóquere tu nobis, et audiámus: non loquátur nobis Dóminus, ne forte moriámur. Et ait Móyses ad pópulum: Nolite timére: ut enim probáret vos, venit Deus, et ut terror illíus esset in vobis, et non peccarétis. Stetítque pópulus de longe. Móyses autem accéssit ad calíginem, in qua erat Deus. Dixit prætérea Dóminus ad Móysen: Hæc dices fíliis Israël: Vos vidístis, quod de cœlo locútus sim vobis. Non faciétis deos argénteos, nec deos áureos faciétis vobis. Altáre de terra faciétis mihi, et offerétis super eo holocáusta et pacífica vestra, oves vestras et boves in omni loco, in quo memória fúerit nóminis mei."}],"Graduale":[{"k":"ref","la":"Ps 6:3-4"},{"k":"text","la":"Miserére mei, Dómine, quóniam infírmus sum: sana me, Dómine,"},{"k":"text","la":"Conturbáta sunt ómnia ossa mea: et ánima mea turbáta est valde.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis."},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangéliim secúndum Matthǽum."},{"k":"ref","la":"Matt 15:1-20"},{"k":"text","la":"In illo témpore: Accessérunt ad Jesum ab Jerosólymis scribæ et pharisǽi, dicéntes: Quare discípuli tui transgrediúntur traditiónem seniórum? Non enim lavant manus suas, cum panem mandúcant. Ipse autem respóndens, ait illis: Quare et vos transgredímini mandátum Dei propter traditiónem vestram? Nam Deus dixit: Honóra patrem et matrem. Et: Qui male díxerit patri vel matri, morte moriátur. Vos autem dícitis: Quicúmque díxerit patri vel matri: munus quodcúmque est ex me, tibi próderit: et non honorificábit patrem suum aut matrem suam: et írritum fecístis mandátum Dei propter traditiónem vestram. Hypócritæ, bene prophetávit de vobis Isaías, dicens: Pópulus hic lábiis me honórat: cor autem eórum longe est a me. Sine causa autem colunt me, docéntes doctrínas et mandáta hóminum. Et convocátis ad se turbis, dixit eis: Audíte, et intellégite. Non quod intrat in os, coínquinat hóminem: sed quod procédit ex ore, hoc coínquinat hóminem. Tunc accedéntes discípuli ejus, dixérunt ei: Scis, quia pharisǽi, audíto verbo hoc, scandalizáti sunt? At ille respóndens, ait: Omnis plantátio, quam non plantávit Pater meus cœléstis, eradicábitur. Sínite illos: cæci sunt et duces cæcórum. Cæcus autem si cæco ducátum præstet, ambo in fóveam cadunt. Respóndens autem Petrus, dixit ei: Edíssere nobis parábolam istam. At ille dixit: Adhuc et vos sine intelléctu estis? Non intellégitis, quia omne, quod in os intrat, in ventrem vadit, et in secéssum emíttitur ? Quæ autem procédunt de ore, de corde éxeunt, et ea coínquinant hóminem: de corde enim éxeunt cogitatiónes malæ, homicídia, adultéria, fornicatiónes, furta, falsa testimónia, blasphémiæ. Hæc sunt, quæ coínquinant hóminem. Non lotis autem mánibus manducáre, non coínquinat hóminem."}],"Offertorium":[{"k":"ref","la":"Ps 108:21"},{"k":"text","la":"Dómine, fac mecum misericórdiam tuam, propter nomen tuum: quia suávis est misericórdia tua."}],"Secreta":[{"k":"text","la":"Súscipe, quǽsumus, Dómine, preces pópuli tui cum oblatiónibus hostiárum: et tua mystéria celebrántes, ab ómnibus nos defénde perículis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 15:10"},{"k":"text","la":"Notas mihi fecísti vias vitæ: adimplébis me lætítia cum vultu tuo, Dómine."}],"Postcommunio":[{"k":"text","la":"Sanctíficet nos, Dómine, qua pasti sumus, mensa cœléstis: et a cunctis erróribus expiátos, supérnis promissiónibus reddat accéptos."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut, qui protectiónis tuæ grátiam quǽrimus, liberáti a malis ómnibus, secúra tibi mente serviámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"1fcf03013ae0bab3":{"t":"Ps 30, 7-8, Ps 30, 2\n(Ps 30, 7-8) Ja se uzdam u Gospodina. Kličem od radosti i veselim se radi milosrđa tvoga, jer si pogledao na poniženje moje. (Ps 30, 2) U tebe se, Gospodine, uzdam. Ne daj da se razočaram ikada. U svojoj me pravednosti izbavi i spasi.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 30, 7-8) Ja se uzdam u Gospodina. Kličem od radosti i veselim se radi milosrđa tvoga, jer si pogledao na poniženje moje."},"dc8fddd0b122dbd2":{"t":"<i>Pomolimo se</i>.\nPodaj nam, molimo, Gospodine, da poučeni spasonosnim postovima i uzdržavajući se od štetnih mana lakše zadobijemo tvoje smilovanje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"17f3682f15a6d66a":{"t":"Izl 20, 12-24\nČitanje knjige Izlaska. Ovo govori Gospodin Bog: Poštuj svoga oca i svoju majku da dugo živiš na zemlji koju će ti dati Bog tvoj Gospodin. Ne ubij. Ne čini preljuba. Ne svjedoči krivo protiv svoga bližnjega. Ne zaželi doma svoga bližnjega. Ne poželi njegove žene, ni sluge, ni sluškinje, ni vola, ni magarca, niti išta što je njegovo. A kad ljudi zapaze gromove, munje, i glas trublje, goru svu u dimu, prestraše se, ne usude se pristupiti bliže, nego reknu Mojsiju: Ti nam govori, a mi ćemo slušati. Neka nam ne govori Gospodin, da ne umremo. Mojsije im reče: Nemojte se bojati! Bog dođe da vas iskuša, da ga se bojite i da ne sagriješite. I ljudi ostanu podalje a Mojsije uđe u oblak gdje je bio Bog. Gospodin reče Mojsiju: Ovo kaži Izraelovim sinovima: Vidjeli ste kad sam govorio s neba. Nemojte sebi praviti ni srebrnih ni zlatnih bogova. Podignite mi žrtvenik od zemlje. Na njemu prinesite svoje žrtve paljenice i pomirnice, svoje ovce i volove na svakom mjestu, gdje se spominje moje ime."},"0a45ec37428fc631":{"t":"Ps 6, 3-4\nSmiluj mi se, Gospodine, jer sam nemoćan. Ozdravi me, Gospodine. Uzdrhtale su sve kosti moje i duša je moja smućena veoma.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega."},"828c0fa21ba41c74":{"t":"Mt 15, 1-20\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme pristupe k Isusu književnici i farizeji iz Jeruzalema i pitaju ga: Zašto tvoji učenici krše predaju starih? Oni ne peru ruke prije jela. On im odgovori: A zašto vi kršite Božju zapovijed zbog svoje predaje? Bog je zapovjedio; Poštuj oca i majku. Tko uvrijedi oca ili svoju majku, neka pogine! A vi kažete: Tko reče ocu ili majci: Što god ja prinesem kao žrtveni dar, koristit će tebi, a ne poštuje svoga oca ili svoju majku, time ste vi dokinuli Božju zapovijed zbog svoje predaje. Licemjeri, dobro je o vama rekao prorok Izaija: Ovaj me narod poštuje ustima, a njegovo je srce daleko od mene. Uzalud misli da me štuje jer naučava ljudske nauke i zapovijedi. Tada dozove k sebi ljude i reče im: Čujte i shvatite! Ne kalja čovjeka što uzlazi kroz usta, nego što izlazi iz usta. Tada se približe učenici i rekoše: Znaš da su se farizeji sablaznili na tvoje riječi? On odgovori: Svaki nasad, koji nije posadio moj nebeski Otac, bit će iščupan. Ostavite ih! Oni su slijepci i vođe slijepaca. Ako slijepac vodi slijepca obojica će pasti u jamu. Tada Petar zamoli: Protumači nama ovu usporedbu. Isus reče: Pa ni vi još ne shvaćate? Ne razumijete li da sve što prolazi kroz usta ulazi u trbuh i izbacuje se? A što izlazi iz usta, izlazi iz srca, i to kalja čovjeka. Iz srca izlaze zle misli, ubojstva, preljubi, bludnosti, krađe, lažna svjedočanstva, psovke. Sve to kalja čovjeka. A jesti neopranim rukama ne kalja čovjeka."},"e1656ea0b671a49b":{"t":"Ps 108, 21\nGospodine, radi imena svoga postupaj sa mnom po milosrđu svome, jer je tvoje milosrđe ugodno."},"be0fa77008269214":{"t":"Primi, molimo, Gospodine, molitve svoga naroda s prikaznim darovima i nas, koji vršimo tvoje tajne brani od svih pogibli.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"38f17e9e8f90de1c":{"t":"Ps 15, 11\nPokazuješ mi stazu života, ispunjaš me radošću što gledam odraz lica tvoga, Gospodine."},"292930c527aeb69d":{"t":"<i>Pomolimo se</i>.\nPosvetila nas, Gospodine, nebeska gozba koju smo blagovali, i očišćene od svih zabluda učinila nas prikladnima za nebeska obećanja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"132b441571d0c354":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nDaj, molimo, svemogući Bože, da ti mi koji molimo za milost tvoje zaštite, izbavljeni od svih zala, služimo bez straha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
